/**
 * Check that `language` denotes English.
 */
export function isEnglish(
  language: string
): boolean {
  return language == "en";
}

/**
 * Check that every set in `langStringSets` has at least one
 * string in English.
 *
 * @remarks
 *
 * This function tests a plain `any` nested in `all`.
 */
export function langStringSetsHaveEnglish(
  langStringSets: Array<AasTypes.LangStringSet>
): boolean {
  return AasCommon.every(
    AasCommon.map(
      langStringSets,
      langStringSet =>
        AasCommon.some(
          AasCommon.map(
            langStringSet.langStrings,
            langString =>
              isEnglish(langString.language)
          )
        )
    )
  );
}

/**
 * Check that the {@link types!IecContent.definition} is defined at least in English
 * for all the specifications whose content is an {@link types!IecContent}.
 *
 * @remarks
 *
 * This function tests an `any` nested in `all`, where the nested `any`
 * iterates over an optional property of a value narrowed by `isinstance`.
 */
export function iecContentsHaveDefinitionInEnglish(
  specifications: Array<AasTypes.Specification>
): boolean {
  return AasCommon.every(
    AasCommon.map(
      specifications,
      specification =>
        !AasTypes.isIecContent(specification.content)
        || (
          (
            ((specification.content as AasTypes.IecContent).definition !== null)
            && (
              AasCommon.some(
                AasCommon.map(
                  (specification.content as AasTypes.IecContent).definition,
                  langString =>
                    isEnglish(langString.language)
                )
              )
            )
          )
        )
    )
  );
}

